import{_ as l,a0 as o,w as r,s as d,I as t,x as a,a1 as e,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"構建一個即時消息應用（一）：模式 | LCTT x X-CMD","titleTemplate":false,"description":"構建一個即時消息應用（一）：模式 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"構建一個即時消息應用（一）：模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"構建一個即時消息應用（一）：模式 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20180705 Building a Messenger App- Schema","title":"構建一個即時消息應用（一）：模式","tag":"201909","desc":""},"relativePath":"201909/20180705 Building a Messenger App- Schema.md","filePath":"[post].md"}'),g={name:"201909/20180705 Building a Messenger App- Schema.md"};function u(E,s,k,T,h,m){const n=o("Link");return r(),d("div",null,[s[31]||(s[31]=t("h1",{id:"構建一個即時消息應用-一-模式",tabindex:"-1"},[a("構建一個即時消息應用（一）：模式 "),t("a",{class:"header-anchor",href:"#構建一個即時消息應用-一-模式","aria-label":"Permalink to “構建一個即時消息應用（一）：模式”"},"​")],-1)),s[32]||(s[32]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201909/27/211458n44f7jvp77lfxxm0.jpg",alt:""})],-1)),t("p",null,[s[3]||(s[3]=a("這是一系列關於構建“即時消息”應用的新帖子。你應該對這類應用並不陌生。有了它們的幫助，我們才可以與朋友暢聊無忌。",-1)),e(n,{href:"https://www.messenger.com/"},{default:i(()=>[...s[0]||(s[0]=[a("Facebook Messenger",-1)])]),_:1}),s[4]||(s[4]=a("、",-1)),e(n,{href:"https://www.whatsapp.com/"},{default:i(()=>[...s[1]||(s[1]=[a("WhatsApp",-1)])]),_:1}),s[5]||(s[5]=a(" 和 ",-1)),e(n,{href:"https://www.skype.com/"},{default:i(()=>[...s[2]||(s[2]=[a("Skype",-1)])]),_:1}),s[6]||(s[6]=a(" 就是其中的幾個例子。正如你所看到的那樣，這些應用允許我們發送圖片、傳輸視頻、錄製音頻、以及和一大幫子人聊天等等。當然，我們的教程應用將會盡量保持簡單，只在兩個用户之間發送文本消息。",-1))]),t("p",null,[s[9]||(s[9]=a("我們將會用 ",-1)),e(n,{href:"https://www.cockroachlabs.com/"},{default:i(()=>[...s[7]||(s[7]=[a("CockroachDB",-1)])]),_:1}),s[10]||(s[10]=a(" 作為 SQL 資料庫，用 ",-1)),e(n,{href:"https://golang.org/"},{default:i(()=>[...s[8]||(s[8]=[a("Go",-1)])]),_:1}),s[11]||(s[11]=a(" 作為後端語言，並且用 JavaScript 來製作 web 應用。",-1))]),s[33]||(s[33]=p(`<p>這是第一篇帖子，我們將會講述資料庫的設計。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE users (</span></span>
<span class="line"><span>    id SERIAL NOT NULL PRIMARY KEY,</span></span>
<span class="line"><span>    username STRING NOT NULL UNIQUE,</span></span>
<span class="line"><span>    avatar_url STRING,</span></span>
<span class="line"><span>    github_id INT NOT NULL UNIQUE</span></span>
<span class="line"><span>);</span></span></code></pre></div>`,2)),t("p",null,[s[13]||(s[13]=a("顯然，這個應用需要一些用户。我們這裏採用社交登錄的形式。由於我選用了 ",-1)),e(n,{href:"https://github.com/"},{default:i(()=>[...s[12]||(s[12]=[a("GitHub",-1)])]),_:1}),s[14]||(s[14]=a("，所以這裏需要保存一個對 GitHub 用户 ID 的引用。",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE conversations (</span></span>
<span class="line"><span>    id SERIAL NOT NULL PRIMARY KEY,</span></span>
<span class="line"><span>    last_message_id INT,</span></span>
<span class="line"><span>    INDEX (last_message_id DESC)</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>每個對話都會引用最近一條消息。每當我們輸入一條新消息時，我們都會更新這個字段。我會在後面添加外鍵約束。</p><p>… 你可能會想，我們可以先對對話進行分組，然後再通過這樣的方式獲取最近一條消息。但這樣做會使查詢變得更加複雜。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE participants (</span></span>
<span class="line"><span>    user_id INT NOT NULL REFERENCES users ON DELETE CASCADE,</span></span>
<span class="line"><span>    conversation_id INT NOT NULL REFERENCES conversations ON DELETE CASCADE,</span></span>
<span class="line"><span>    messages_read_at TIMESTAMPTZ NOT NULL DEFAULT now(),</span></span>
<span class="line"><span>    PRIMARY KEY (user_id, conversation_id)</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>儘管之前我提到過對話只會在兩個用户之間進行，但我們還是採用了允許向對話中添加多個參與者的設計。因此，在對話和用户之間有一個參與者表。</p><p>為了知道用户是否有未讀消息，我們在消息表中添加了“讀取時間”（<code>messages_read_at</code>）字段。每當用户在對話中讀取消息時，我們都會更新它的值，這樣一來，我們就可以將它與對話中最後一條消息的“創建時間”（<code>created_at</code>）字段進行比較。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE messages (</span></span>
<span class="line"><span>    id SERIAL NOT NULL PRIMARY KEY,</span></span>
<span class="line"><span>    content STRING NOT NULL,</span></span>
<span class="line"><span>    user_id INT NOT NULL REFERENCES users ON DELETE CASCADE,</span></span>
<span class="line"><span>    conversation_id INT NOT NULL REFERENCES conversations ON DELETE CASCADE,</span></span>
<span class="line"><span>    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),</span></span>
<span class="line"><span>    INDEX(created_at DESC)</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>儘管我們將消息表放在最後，但它在應用中相當重要。我們用它來保存對創建它的用户以及它所出現的對話的引用。而且還可以根據“創建時間”（<code>created_at</code>）來創建索引以完成對消息的排序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE conversations</span></span>
<span class="line"><span>ADD CONSTRAINT fk_last_message_id_ref_messages</span></span>
<span class="line"><span>FOREIGN KEY (last_message_id) REFERENCES messages ON DELETE SET NULL;</span></span></code></pre></div><p>我在前面已經提到過這個外鍵約束了，不是嗎:D</p><p>有這四張表就足夠了。你也可以將這些查詢保存到一個文件中，並將其通過管道傳送到 Cockroach CLI。</p><p>首先，我們需要啓動一個新節點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cockroach start --insecure --host 127.0.0.1</span></span></code></pre></div><p>然後創建資料庫和這些表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cockroach sql --insecure -e &quot;CREATE DATABASE messenger&quot;</span></span>
<span class="line"><span>cat schema.sql | cockroach sql --insecure -d messenger</span></span></code></pre></div><p>這篇帖子就到這裏。在接下來的部分中，我們將會介紹「登錄」，敬請期待。</p>`,16)),t("ul",null,[t("li",null,[e(n,{href:"https://github.com/nicolasparada/go-messenger-demo"},{default:i(()=>[...s[15]||(s[15]=[a("源代碼",-1)])]),_:1})])]),s[35]||(s[35]=t("hr",null,null,-1)),t("p",null,[s[17]||(s[17]=a("via: ",-1)),e(n,{href:"https://nicolasparada.netlify.com/posts/go-messenger-schema/"},{default:i(()=>[...s[16]||(s[16]=[a("https://nicolasparada.netlify.com/posts/go-messenger-schema/",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=a("作者：",-1)),e(n,{href:"https://nicolasparada.netlify.com/"},{default:i(()=>[...s[18]||(s[18]=[a("Nicolás Parada",-1)])]),_:1}),s[23]||(s[23]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 譯者：",-1)),e(n,{href:"https://github.com/PsiACE"},{default:i(()=>[...s[20]||(s[20]=[a("PsiACE",-1)])]),_:1}),s[25]||(s[25]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[28]||(s[28]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[27]||(s[27]=[a("Linux 中國",-1)])]),_:1}),s[30]||(s[30]=a(" 榮譽推出",-1))])])}const C=l(g,[["render",u]]);export{N as __pageData,C as default};
